/bin/bash -lc "python3 - <<'PY'
import json
p='results/run60/metrics.jsonl'
for l in open(p):
 d=json.loads(l); x=d['data'];
 if 'val-core/openai/gsm8k/acc/mean@1' in x: print(d['step'],x['val-core/openai/gsm8k/acc/mean@1'])
PY
printf '\\nprep log:\\n'; cat results/run60/data_prep.log
printf '\\nrollout samples:\\n'; for f in results/run60/rollouts/1.jsonl results/run60/rollouts/60.jsonl results/run60/val_generations/0.jsonl results/run60/val_generations/60.jsonl; do echo "'$f; head -2 $f; done'

